\begin{document}

\section{জীববিজ্ঞান প্রথম পত্র}

\subsection{সৃজনশীল প্রশ্ন}

\begin{enumerate}
    \item
    \begin{enumerate}
        \item প্রতিলিপন কি?
        \item আদিকোষ ও প্রকৃত কোষের পার্থক্য লিখ।
        \item উদ্দীপকে প্রদর্শিত অনুর রাসায়নিক গঠন বর্ণনা কর।
        \item উদ্দীপকের অগুটি চরিত্র সংখ্যার্গে অনন্য ভূমিকা পালন করে তা বিশ্লেষণ কর।
    \end{enumerate}
    \item
    বর্ণময় উদ্দিদ জগতে রয়েছে নানান বর্ণের বাহার। প্রায় সকল উদ্দিদের পাতা সবুজ হয়যাকর্ষ। ফুলগুলো সাধারণত লাল, সাদা, গোলাপী, বেগুনী, নীল। তাছাড়া আরো আছে বিচিত্র সব বর্ণ। লোভনীয় বর্ণে আকর্ষিত হয় পত্তনকূল, নিশ্চিত হয় পরাগায়ন।
    \begin{enumerate}
        \item রেশ্মিকন কি?
        \item আত্মাঘাতী থলি বলতে কী বুঝা?
        \item উদ্দীপকের অঙ্গাগুটির গঠন বর্ণনা কর।
        \item উদ্দীপকের অঙ্গাগুটি উদ্দিদ জীবনে যে গুরুত্ব বহন করে তা বিশ্লেষণ কর।
    \end{enumerate}
    \item জীবদেহের গঠনকে ইটের তৈরি সুরম্য ইমারত এর সাথে তুলনা করা যেতে পারে, যেমন একটি ইটের উপর ইট বসিয়ে সুরম্য ইমারত গড়ে ওঠে। তেমনি একটির পর একটি স্বপ্নজনশীল, বৈষম্যভেদ পর্দাবেষ্টিত অসংখ্য একক দিয়ে জীবদেহ গঠিত।
\end{enumerate}

\end{document}

